import {Router} from 'express';
import {randomUUID} from 'node:crypto';
import {store} from './store.js';
import {validateEmail} from './validate.js';

export const users = Router();

users.get('/', (req, res) => {
  res.json(store.list(typeof req.query.q === 'string' ? req.query.q : undefined));
});

users.post('/', (req, res) => {
  const {name, email} = req.body ?? {};
  if (typeof name !== 'string' || !name || typeof email !== 'string' || !validateEmail(email)) return res.status(400).json({error: 'invalid'});
  res.status(201).json(store.put({id: randomUUID(), name, email, role: 'member'}));
});

// Added recently: delete a user.
users.delete('/:id', (req, res) => {
  store.remove(req.params.id);
  res.status(204).end();
});

